export function originalSpringStep(position, velocity, target, dt) {
  const step = Math.min(Math.max(dt, 0), 1 / 60);
  const acceleration = 180 * (target - position) - 24 * velocity;
  const nextVelocity = velocity + acceleration * step;
  return { position: position + nextVelocity * step, velocity: nextVelocity };
}
